const body = $json.body ?? $json;
const allowedTimelines = ['this_week', 'within_30_days', 'within_90_days', 'researching'];
const text = (value, max) => typeof value === 'string' ? value.trim().replace(/\s+/g, ' ').slice(0, max) : '';
const requestId = text(body.request_id, 120);
const customerName = text(body.customer_name, 120);
const make = text(body.preferred_make, 80);
const bodyType = text(body.body_type, 30);
const notes = text(body.notes, 500);
const budget = typeof body.budget_aed === 'number' || (typeof body.budget_aed === 'string' && body.budget_aed.trim()) ? Number(body.budget_aed) : NaN;
const timeline = text(body.purchase_timeline, 30);
const errors = [];
if (typeof body.request_id !== 'string' || body.request_id.length > 120) errors.push({field:'request_id',message:'Use a string up to 120 characters'});
if (bodyType && !['SUV','Sedan','Coupe','Hatchback','Pickup','Van'].includes(bodyType)) errors.push({field:'body_type',message:'Unsupported body type'});
if (!requestId) errors.push({ field: 'request_id', message: 'Required' });
if (!customerName) errors.push({ field: 'customer_name', message: 'Required' });
if (!Number.isFinite(budget) || budget <= 0 || budget > 10000000) errors.push({ field: 'budget_aed', message: 'Must be between 1 and 10000000' });
if (!allowedTimelines.includes(timeline)) errors.push({ field: 'purchase_timeline', message: 'Unsupported timeline' });
const normalized = { request_id: requestId, customer_name: customerName, preferred_make: make || null, body_type: bodyType || null, budget_aed: budget, purchase_timeline: timeline, notes: notes || null, currency: 'AED' };
const canonical = JSON.stringify(normalized);
const payloadHash = canonical;
return [{ json: { normalized, payload_hash: payloadHash, correlation_id: `${requestId || 'invalid'}-${Date.now()}`, valid: errors.length === 0, errors } }];

const input = $('Code - Validate and Normalize').first().json;
const claim = $('HTTP - Claim Enquiry RPC').first().json.body;
const rows = $json.body;
if (!Array.isArray(rows) || !claim.claim_token || rows.length >= 1000 || rows.some(v => !v.id || typeof v.make !== 'string' || typeof v.body_type !== 'string' || !Number.isFinite(Number(v.asking_price_aed)) || Number(v.asking_price_aed)<=0 || !Number.isFinite(Number(v.mileage_km)))) return [{json:{failure:true}}];
const preferences = input.normalized;
const eligible = rows.filter(vehicle => vehicle.status === 'advertised' && Number(vehicle.asking_price_aed) <= preferences.budget_aed);
const ranked = eligible.map(vehicle => { const makeMatch = preferences.preferred_make && vehicle.make.toLowerCase() === preferences.preferred_make.toLowerCase(); const bodyMatch = preferences.body_type && vehicle.body_type.toLowerCase() === preferences.body_type.toLowerCase(); const score = (makeMatch ? 2 : 0) + (bodyMatch ? 1 : 0); return { ...vehicle, match_reasons: [makeMatch ? 'requested make' : 'alternative make', bodyMatch ? 'requested body type' : 'alternative body type', 'within budget'], _score: score }; }).sort((a, b) => b._score - a._score || Number(a.asking_price_aed)-Number(b.asking_price_aed) || Number(a.mileage_km)-Number(b.mileage_km) || a.stock_number.localeCompare(b.stock_number)).slice(0, 3).map(({ _score, ...vehicle }) => vehicle);
const exact = ranked.some(v => (!preferences.preferred_make || v.make.toLowerCase() === preferences.preferred_make.toLowerCase()) && (!preferences.body_type || v.body_type.toLowerCase() === preferences.body_type.toLowerCase()));
const outcome = ranked.length === 0 ? 'no_match' : (exact ? 'exact_match' : 'alternative');
const priority = preferences.purchase_timeline === 'this_week' || exact ? 'high' : preferences.purchase_timeline === 'within_30_days' ? 'medium' : 'low';
const reasons = ['YallaMotor listing snapshot from 20 September 2026; price and availability require seller confirmation.', outcome === 'exact_match' ? 'At least one vehicle matches the stated preferences.' : outcome === 'alternative' ? 'No exact preference match was available; alternatives stay within budget.' : 'No available vehicle is within the stated budget.', `Purchase timeline: ${preferences.purchase_timeline}`];
const advisorBrief = outcome === 'no_match' ? 'Clarify whether the buyer can increase the budget or change preferences before follow-up.' : `Contact ${preferences.customer_name} with ${ranked.length} advertised Dubai vehicle option${ranked.length === 1 ? '' : 's'} and confirm availability.`;
return [{ json: { request_id: preferences.request_id, claim_token: claim.claim_token, normalized_preferences: preferences, shortlist: ranked, outcome, priority, reasons, advisor_brief: advisorBrief, fetched_at: new Date().toISOString() } }];
